import React, { useState } from 'react';

function CalorieCalculatorForm() {
  const [age, setAge] = useState('');
  const [gender, setGender] = useState('');
  const [weight, setWeight] = useState('');
  const [height, setHeight] = useState('');
  const [activityLevel, setActivityLevel] = useState('');
  const [calorieNeeds, setCalorieNeeds] = useState(null);
  const [errorMessage, setErrorMessage] = useState('');

  const handleSubmit = (e) => {
    e.preventDefault();

    if (!age || !gender || !weight || !height || !activityLevel) {
      setErrorMessage('Please fill in all fields');
      return;
    }

    if (isNaN(age) || isNaN(weight) || isNaN(height)) {
      setErrorMessage('Age, weight, and height must be numeric values');
      return;
    }

    // Calculate calorie needs based on input values
    // Implement your calorie calculation logic here

    // Display the result
    setCalorieNeeds(/* calculated calorie needs */);
  };

  return (
    <div>
      <h2>Calorie Calculator</h2>
      {errorMessage && <p style={{ color: 'red' }}>{errorMessage}</p>}
      <form onSubmit={handleSubmit}>
        <div>
          <label>
            Age:
            <input
              type="number"
              value={age}
              onChange={(e) => setAge(e.target.value)}
              required
            />
          </label>
        </div>
        <div>
          <label>
            Gender:
            <select
              value={gender}
              onChange={(e) => setGender(e.target.value)}
              required
            >
              <option value="">Select</option>
              <option value="male">Male</option>
              <option value="female">Female</option>
            </select>
          </label>
        </div>
        <div>
          <label>
            Weight (kg):
            <input
              type="number"
              value={weight}
              onChange={(e) => setWeight(e.target.value)}
              required
            />
          </label>
        </div>
        <div>
          <label>
            Height (cm):
            <input
              type="number"
              value={height}
              onChange={(e) => setHeight(e.target.value)}
              required
            />
          </label>
        </div>
        <div>
          <label>
            Activity Level:
            <select
              value={activityLevel}
              onChange={(e) => setActivityLevel(e.target.value)}
              required
            >
              <option value="">Select</option>
              <option value="sedentary">Sedentary</option>
              <option value="lightlyActive">Lightly Active</option>
              <option value="moderatelyActive">Moderately Active</option>
              <option value="veryActive">Very Active</option>
              <option value="extraActive">Extra Active</option>
            </select>
          </label>
        </div>
        <button type="submit">Calculate</button>
      </form>

      {/* Display calorie needs result */}
      {calorieNeeds && (
        <div>
          <h3>Calorie Needs:</h3>
          <p>{calorieNeeds} calories per day</p>
        </div>
      )}
    </div>
  );
}

export default CalorieCalculatorForm;
